def compute(vars):
    years_exceeding = sum(1 for value in (vars["v1"], vars["v2"]) if value > 3000)
    return {
        "value": years_exceeding,
        "trace": {
            "threshold": 3000,
            "years_exceeding": years_exceeding,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "years"
            }
        }
    }
